#!/usr/bin/env python3
"""Turn MuPDF's Makelists into CMake source lists.

MuPDF ships no CMake build, and since 1.26 no iOS target either, so
NitroFlipper compiles the sources itself. Rather than hand-maintaining file
lists that drift every release, this reads the same `Makelists` the upstream
Makefile reads and emits `mupdf_sources.cmake`.

Upgrading MuPDF is then: bump the version and hash in CMakeLists.txt, rerun
this, review the diff. A source file appearing or vanishing upstream shows up
as a reviewable line rather than a link error.

Usage: extract_sources.py <path-to-mupdf-source> <output.cmake>
"""
import re
import sys
from pathlib import Path

# Groups we compile. Anything absent here is deliberately excluded -- see
# CMakeLists.txt for the feature flags that must match.
WANTED = [
    "FREETYPE", "GUMBO", "HARFBUZZ", "JBIG2DEC",
    "LCMS2", "OPENJPEG", "BROTLI", "ZLIB", "LIBJPEG",
]

ASSIGN = re.compile(r"^([A-Z0-9_]+)_SRC\s*\+?=\s*(\S+)\s*$")


def parse(makelists: Path) -> dict[str, list[str]]:
    groups: dict[str, list[str]] = {}
    for line in makelists.read_text(encoding="utf-8", errors="replace").splitlines():
        m = ASSIGN.match(line.strip())
        if not m:
            continue
        name, path = m.group(1), m.group(2)
        if "$" in path:  # a variable reference, not a file
            continue
        groups.setdefault(name, []).append(path)
    return groups


def main() -> int:
    if len(sys.argv) != 3:
        print(__doc__, file=sys.stderr)
        return 2
    root, out = Path(sys.argv[1]), Path(sys.argv[2])
    makelists = root / "Makelists"
    if not makelists.is_file():
        print(f"no Makelists under {root}", file=sys.stderr)
        return 1

    groups = parse(makelists)
    missing = [g for g in WANTED if g not in groups]
    if missing:
        print(f"Makelists has no source list for: {', '.join(missing)}", file=sys.stderr)
        return 1

    lines = [
        "# Generated by third_party/mupdf/extract_sources.py -- do not edit.",
        f"# Parsed from Makelists of the pinned MuPDF source tree.",
        "",
    ]
    for group in WANTED:
        files = groups[group]
        # Verify every listed file actually exists, so a rename upstream fails
        # here with a clear message instead of at link time.
        for f in files:
            if not (root / f).is_file():
                print(f"{group}_SRC lists a missing file: {f}", file=sys.stderr)
                return 1
        lines.append(f"set(MUPDF_{group}_SRC")
        lines.extend(f"  ${{MUPDF_DIR}}/{f}" for f in files)
        lines.append(")")
        lines.append("")

    out.write_text("\n".join(lines), encoding="utf-8")
    total = sum(len(groups[g]) for g in WANTED)
    print(f"wrote {out} ({total} thirdparty sources across {len(WANTED)} groups)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
